package com.bank.statement.service;

import com.bank.statement.model.PageNode;
import java.util.logging.Logger;

// Finds the middle statement page in a single pass.
public class StatementNavigator {
    private static final Logger log = Logger.getLogger(StatementNavigator.class.getName());

    public PageNode findMiddle(PageNode head) {
        PageNode slow = head;
        PageNode fast = head;

        // For even length this stops with slow on the SECOND middle.
        while (fast != null && fast.next != null) {
            slow = slow.next;        // one step
            fast = fast.next.next;   // two steps
        }
        final String mid = (slow == null ? "none" : slow.pageId);
        log.info(() -> "Middle page = " + mid);
        return slow;
    }
}
