package com.bank.statement;

import com.bank.statement.model.PageNode;
import com.bank.statement.service.StatementNavigator;
import java.util.logging.Logger;

public class StatementNavDemo {
    private static final Logger log = Logger.getLogger(StatementNavDemo.class.getName());

    public static void main(String[] args) {
        StatementNavigator nav = new StatementNavigator();

        // Odd length: P1 -> P2 -> P3 -> P4 -> P5 (middle P3)
        PageNode odd = chain(new String[]{"P1", "P2", "P3", "P4", "P5"});
        log.info(() -> "Odd middle: " + nav.findMiddle(odd).pageId);

        // Even length: P1 -> P2 -> P3 -> P4 (second middle P3)
        PageNode even = chain(new String[]{"P1", "P2", "P3", "P4"});
        log.info(() -> "Even middle: " + nav.findMiddle(even).pageId);
    }

    private static PageNode chain(String[] ids) {
        PageNode dummy = new PageNode("D");
        PageNode tail = dummy;
        for (String id : ids) { tail.next = new PageNode(id); tail = tail.next; }
        return dummy.next;
    }
}
